use super::{api,ctx};
use crate::support_model::*;
use leptos::{prelude::*,task::spawn_local};
use serde_json::{Value,json};

#[component]
pub(super) fn SupportInbox()->impl IntoView {
    let c=ctx();let refresh=RwSignal::new(0u64);let kind=RwSignal::new(String::new());let status=RwSignal::new(String::new());let query=RwSignal::new(String::new());
    let allowed=c.session.get_value().user.publisher();let admin=c.session.get_value().user.role=="admin";
    let records=LocalResource::new(move||{let _=refresh.get();async move{api::<Vec<SupportRecord>>("GET","/api/cms/support","",Value::Null).await}});
    if !allowed{return view!{<h1>"Support requests"</h1><p>"Editors and administrators can review these private records."</p>}.into_any();}
    view!{<div class="page-heading"><div><p class="eyebrow">"TURN INTEREST INTO A CONVERSATION"</p><h1>"Support requests"</h1><p>"Real enquiries and offers saved from the website."</p></div><button class="button" on:click=move|_|refresh.update(|n|*n+=1)>"Refresh requests"</button></div><div class="editor-panel support-inbox-note"><h2>"What these records mean"</h2><p>"Giving and membership entries are enquiries. Volunteer offers are not bookings. Newsletter entries record interest and consent, not an active subscription. Review the request, arrange follow-up, and record your progress here."</p><p>"No automatic emails are sent. Use an approved service for follow-up, honour withdrawals, and delete personal details when no longer needed."</p></div>
        <div class="support-inbox-filters"><label class="field"><span>"Request type"</span><select aria-label="Request type" prop:value=move||kind.get() on:change=move|e|kind.set(event_target_value(&e))><option value="">"All types"</option>{KINDS.iter().map(|(k,l,_)|view!{<option value=*k>{*l}</option>}).collect_view()}</select></label><label class="field"><span>"Request status"</span><select aria-label="Request status" prop:value=move||status.get() on:change=move|e|status.set(event_target_value(&e))><option value="">"All statuses"</option><option value="new">"New"</option><option value="in-progress">"In progress"</option><option value="closed">"Closed"</option><option value="withdrawn">"Withdrawn"</option></select></label><label class="field"><span>"Search requests"</span><input type="search" prop:value=move||query.get() on:input=move|e|query.set(event_target_value(&e)) placeholder="Name, email, or reference"/></label></div>
        {admin.then(||view!{<div class="support-export"><Show when=move||!kind.get().is_empty() fallback=||view!{<p class="small-note">"Choose a request type to export its contact records."</p>}><a class="button" download href=move||format!("/api/cms/support/export/{}",kind.get())>"Export this type as CSV"</a><p class="small-note">"Includes all non-withdrawn requests of this type, regardless of search or status filters. Exported newsletter interest is not a verified subscriber list."</p></Show></div>})}
        {move||records.get().map(|result|match result{Err(e)=>view!{<p role="alert" class="notice error">{e}</p>}.into_any(),Ok(all)=>{let q=query.get().to_lowercase();let filtered:Vec<_>=all.into_iter().filter(|r|(kind.get().is_empty()||r.kind==kind.get())&&(status.get().is_empty()||r.status==status.get())&&format!("{} {} {}",r.name,r.email,r.reference).to_lowercase().contains(&q)).collect();let count=filtered.len();view!{<p class="small-note" role="status">{format!("{count} requests · Showing the newest {}",count.min(50))}</p>{(count==0).then(||view!{<div class="editor-panel"><h2>"A place for the next connection."</h2><p>"Requests will appear here when visitors save a form. Try another filter if you expected a record."</p></div>})}<div class="support-inbox-list">{filtered.into_iter().take(50).map(|record|view!{<RequestRow record admin on_saved=Callback::new(move|_|refresh.update(|n|*n+=1))/>}).collect_view()}</div>}.into_any()}})}
        <Show when=move||records.get().is_none()><p role="status">"Loading private requests…"</p></Show>}.into_any()
}
#[component]
fn RequestRow(record:SupportRecord,admin:bool,on_saved:Callback<()>)->impl IntoView {
    let c=ctx();let saved=StoredValue::new(record.clone());let status=RwSignal::new(record.status.clone());let note=RwSignal::new(record.note.clone());let busy=RwSignal::new(false);let error=RwSignal::new(String::new());let deleting=RwSignal::new(false);let withdrawn=record.status=="withdrawn";
    let update=move|delete:bool|{busy.set(true);error.set(String::new());spawn_local(async move{let r=saved.get_value();match api::<Value>("POST",&format!("/api/cms/support/{}",r.id),&c.session.get_value().csrf,json!({"version":r.version,"status":status.get_untracked(),"note":note.get_untracked(),"delete":delete})).await{Ok(_)=>{c.notice.set(if delete{"Request deleted."}else{"Request updated."}.into());on_saved.run(());},Err(e)=>error.set(e)}busy.set(false);});};
    view!{<details class="editor-panel support-request" data-reference=record.reference.clone()><summary><span><strong>{if record.name.is_empty(){label(&record.kind).to_string()}else{record.name.clone()}}</strong><small>{format!("{} · {}",label(&record.kind),record.reference)}</small></span><span class="badge">{record.status.clone()}</span></summary><div class="support-request-body"><dl><div><dt>"Received"</dt><dd>{record.created}</dd></div><div><dt>"Email"</dt><dd>{if record.email.is_empty(){"Removed after withdrawal".into()}else{record.email}}</dd></div><div><dt>"Interest"</dt><dd>{area_label(&record.area)}</dd></div>{(!record.amount.is_empty()).then(||view!{<div><dt>"Indicative amount"</dt><dd>{format!("USD {} · Not a payment",record.amount)}</dd></div>})}{(!record.availability.is_empty()).then(||view!{<div><dt>"Location & availability"</dt><dd>{record.availability}</dd></div>})}<div><dt>"Consent record"</dt><dd>{record.consent_version}</dd></div></dl>{(!record.message.is_empty()).then(||view!{<div class="support-request-message"><h3>"Their message"</h3><p>{record.message}</p></div>})}
        {(!withdrawn).then(||view!{<label class="field"><span>"Progress"</span><select aria-label="Progress" prop:value=move||status.get() on:change=move|e|status.set(event_target_value(&e))><option value="new">"New"</option><option value="in-progress">"In progress"</option><option value="closed">"Closed"</option></select></label><label class="field"><span>"Private follow-up note"</span><textarea maxlength="2000" rows="3" prop:value=move||note.get() on:input=move|e|note.set(event_target_value(&e))/></label><button class="button primary" disabled=busy on:click=move|_|update(false)>"Save follow-up"</button>})}
        <p role="alert" class="form-error">{error}</p>{admin.then(||view!{<div class="support-delete"><Show when=move||deleting.get() fallback=move||view!{<button class="text-button" on:click=move|_|deleting.set(true)>"Delete request"</button>}><p>"Permanently delete this request and its contact details from the active inbox?"</p><button class="button danger" disabled=busy on:click=move|_|update(true)>"Delete permanently"</button><button class="text-button" on:click=move|_|deleting.set(false)>"Keep request"</button></Show></div>})}</div></details>}
}
